import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test(
  "Upload a document",
  { tag: "@DOC-01" },
  async ({ apiAs }) => {
    // Background: signed in as member, and a vendor in status "draft"
    const member = await apiAs("member");
    const vendorName = uniqueName("Doc Vendor");
    const createVendor = await member.post("/api/vendors", {
      data: {
        name: vendorName,
        category: "services",
        contact_email: `${uniqueName("doc-contact").replace(/[^a-z0-9]/gi, "").toLowerCase()}@example.test`,
      },
    });
    expect(createVendor.status()).toBe(201);
    const vendor = await createVendor.json();
    expect(vendor.status).toBe("draft");

    // When I upload "insurance_certificate.txt" as kind "insurance_certificate"
    const filename = "insurance_certificate.txt";
    const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: filename,
          mimeType: "text/plain",
          buffer: fs.readFileSync(sample(filename)),
        },
      },
    });

    // Then the response status is 201
    expect(response.status()).toBe(201);
    const document = await response.json();

    // And the document status is "processing"
    expect(document.status).toBe("processing");
    expect(document.kind).toBe("insurance_certificate");
    expect(document.vendor_id).toBe(vendor.id);

    // And an audit event "document.uploaded" is recorded
    const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditResponse.status()).toBe(200);
    const audit = await auditResponse.json();
    const actions = (audit.items as { action: string }[]).map((event) => event.action);
    expect(actions).toContain("document.uploaded");
  },
);
